+  if (is.finite(left) && is.finite(right)) {
+    return(seq(left, right, length.out = 201L))
+  }
+  if (is.finite(left) && is.infinite(right)) {
+    distances <- exp(seq(log(1e-4), log(128), length.out = 201L))
+    return(left + distances)
+  }
+  if (is.infinite(left) && is.finite(right)) {
+    distances <- exp(seq(log(128), log(1e-4), length.out = 201L))
+    return(right - distances)
+  }
+
+  c(seq(-16, 16, length.out = 201L), -32, 32)
+}
+
+.ars_concavity_tolerance <- function(slopes) {
+  1e-6 + 1e-5 * max(1, abs(slopes), na.rm = TRUE)
+}
+
+.ars_check_log_concavity <- function(x, h, where = "") {
+  keep <- is.finite(h) & is.finite(x)
+  if (sum(keep) < 3L) {
+    return(invisible(TRUE))
+  }
+
+  x <- x[keep]
+  h <- h[keep]
+  order_x <- order(x)
+  x <- x[order_x]
+  h <- h[order_x]
+  distinct <- c(TRUE, diff(x) > 0)
+  x <- x[distinct]
+  h <- h[distinct]
+  if (length(x) < 3L) {
+    return(invisible(TRUE))
+  }
+
+  slopes <- diff(h) / diff(x)
+  if (any(!is.finite(slopes))) {
+    .ars_error("could not form finite log-density slopes")
+  }
+  tolerance <- .ars_concavity_tolerance(slopes)
+  if (any(diff(slopes) > tolerance)) {
+    suffix <- if (nzchar(where)) paste0(" during ", where) else ""
+    .ars_error(paste0("density is not log-concave", suffix,
+                      " (log-density slopes increase)"))
+  }
+  invisible(TRUE)
+}
+
+.ars_check_diagnostic_grid <- function(log_density, domain) {
+  points <- .ars_diagnostic_points(domain)
+  values <- log_density(points)
+  finite_values <- is.finite(values)
+
+  # A log-concave density has an interval as its positive support.  Ignore
+  # zero-density tails, but reject a positive gap inside the support.
+  indices <- which(finite_values)
+  if (length(indices) >= 2L && any(diff(indices) > 1L)) {
+    .ars_error("density is not log-concave (positive support is not an interval)")
+  }
+  if (sum(finite_values) >= 3L) {
+    .ars_check_log_concavity(points[finite_values], values[finite_values],
+                             "the initial diagnostic grid")
+  }
+  invisible(TRUE)
+}
+
+.ars_initial_knots <- function(log_density, domain) {
+  candidates <- sort(unique(.ars_candidate_points(domain)))
+  values <- log_density(candidates)
+  valid <- is.finite(values)
+  if (sum(valid) < 2L) {
+    .ars_error("density must be positive at at least two interior points of domain")
+  }
+
+  x <- candidates[valid]
+  h <- values[valid]
+  .ars_check_log_concavity(x, h, "initialization")
+  list(x = x, h = h)
+}
+
+.ars_numerical_slopes <- function(x, h, log_density, domain) {
+  slopes <- numeric(length(x))
+  for (i in seq_along(x)) {
+    scale <- max(1, abs(x[i]))
+    step <- max(1e-6, 1e-5 * scale)
+    if (is.finite(domain[1L])) {
+      step <- min(step, (x[i] - domain[1L]) / 2)
+    }
+    if (is.finite(domain[2L])) {
+      step <- min(step, (domain[2L] - x[i]) / 2)
+    }
+    if (!is.finite(step) || step <= 0) {
+      .ars_error("could not choose a finite-difference step for the density")
+    }
+
+    left_x <- x[i] - step
+    right_x <- x[i] + step
+    left_h <- log_density(left_x)[1L]
+    right_h <- log_density(right_x)[1L]
+    if (is.finite(left_h) && is.finite(right_h)) {
+      slopes[i] <- (right_h - left_h) / (2 * step)
+    } else if (is.finite(right_h) && is.finite(h[i])) {
+      slopes[i] <- (right_h - h[i]) / step
+    } else if (is.finite(left_h) && is.finite(h[i])) {
+      slopes[i] <- (h[i] - left_h) / step
+    } else {
+      .ars_error("could not estimate a finite log-density slope")
+    }
+  }
+
+  if (any(!is.finite(slopes))) {
+    .ars_error("density has a non-finite numerical log-density slope")
+  }
+  tolerance <- .ars_concavity_tolerance(slopes)
+  if (length(slopes) > 1L && any(diff(slopes) > tolerance)) {
+    .ars_error("density is not log-concave (numerical tangent slopes increase)")
+  }
+  slopes
+}
+
+.ars_build_hull <- function(x, h, slopes, domain) {
+  order_x <- order(x)
+  x <- x[order_x]
+  h <- h[order_x]
+  slopes <- slopes[order_x]
+  distinct <- c(TRUE, diff(x) > 0)
+  x <- x[distinct]
+  h <- h[distinct]
+  slopes <- slopes[distinct]
+  m <- length(x)
+
+  if (m < 2L) {
+    .ars_error("at least two distinct positive-density knots are required")
+  }
+  if (is.infinite(domain[1L]) && slopes[1L] <= 0) {
+    .ars_error("left tail envelope is not integrable; add a valid left-tail knot")
+  }
+  if (is.infinite(domain[2L]) && slopes[m] >= 0) {
+    .ars_error("right tail envelope is not integrable; add a valid right-tail knot")
+  }
+
+  intercepts <- h - slopes * x
+  boundaries <- rep(NA_real_, m + 1L)
+  boundaries[1L] <- domain[1L]
+  boundaries[m + 1L] <- domain[2L]
+  for (i in seq_len(m - 1L)) {
+    slope_difference <- slopes[i] - slopes[i + 1L]
+    intercept_difference <- intercepts[i + 1L] - intercepts[i]
+    scale <- max(1, abs(slopes[i]), abs(slopes[i + 1L]),
+                 abs(intercepts[i]), abs(intercepts[i + 1L]))
+    if (abs(slope_difference) <= 1e-10 * scale) {
+      if (abs(intercept_difference) > 1e-7 * scale) {
+        .ars_error("could not construct an ordered tangent envelope; density may not be log-concave")
+      }
+      # Exact affine log densities (the exponential is an important case)
+      # have coincident tangents, so any split between their knots is valid.
+      boundaries[i + 1L] <- (x[i] + x[i + 1L]) / 2
+    } else {
+      boundaries[i + 1L] <- intercept_difference / slope_difference
+    }
+
+    tolerance <- 1e-7 * max(1, abs(x[i]), abs(x[i + 1L]))
+    if (!is.finite(boundaries[i + 1L]) ||
+        boundaries[i + 1L] < x[i] - tolerance ||
+        boundaries[i + 1L] > x[i + 1L] + tolerance) {
+      .ars_error("tangent intersections are not ordered; density may not be log-concave")
+    }
+  }
+
+  if (any(diff(boundaries) <= 0)) {
+    .ars_error("tangent envelope has non-increasing segment boundaries")
+  }
+
+  list(x = x, h = h, slopes = slopes, intercepts = intercepts,
+       boundaries = boundaries)
+}
+
+.ars_log_integral_linear <- function(slope, intercept, left, right) {
+  if (is.finite(left) && is.finite(right)) {
+    width <- right - left
+    if (width <= 0) {
+      return(-Inf)
+    }
+    q <- slope * width
+    if (abs(q) < 1e-6) {
+      return(intercept + slope * left + log(width) + q / 2)
+    }
+    if (q > 0) {
+      return(intercept + slope * right + log1p(-exp(-q)) - log(slope))
+    }
+    return(intercept + slope * left + log1p(-exp(q)) - log(-slope))
+  }
+
+  if (!is.finite(left) && is.finite(right) && slope > 0) {
+    return(intercept + slope * right - log(slope))
+  }
+  if (is.finite(left) && !is.finite(right) && slope < 0) {
+    return(intercept + slope * left - log(-slope))
+  }
+  .ars_error("piecewise-exponential envelope has a non-integrable segment")
+}
+
+.ars_sample_segment <- function(slope, left, right) {
+  u <- runif(1L)
+  if (!is.finite(left)) {
+    # The segment is integrable only for a positive slope.
+    return(right + log1p(-u) / slope)
+  }
+  if (!is.finite(right)) {
+    # The segment is integrable only for a negative slope.
+    return(left - log1p(-u) / (-slope))
+  }
+
+  width <- right - left
+  q <- slope * width
+  if (abs(q) < 1e-8) {
+    return(left + u * width)
+  }
+  if (q > 0) {
+    log_value <- q + log(u + (1 - u) * exp(-q))
+  } else {
+    log_value <- log((1 - u) + u * exp(q))
+  }
+  left + log_value / slope
+}
+
+.ars_sample_from_hull <- function(hull) {
+  log_weights <- vapply(seq_along(hull$slopes), function(i) {
+    .ars_log_integral_linear(hull$slopes[i], hull$intercepts[i],
+                             hull$boundaries[i], hull$boundaries[i + 1L])
+  }, numeric(1L))
+  if (any(!is.finite(log_weights))) {
+    .ars_error("could not compute finite proposal segment weights")
+  }
+  maximum <- max(log_weights)
+  weights <- exp(log_weights - maximum)
+  segment <- sample.int(length(weights), size = 1L, prob = weights)
+  value <- .ars_sample_segment(hull$slopes[segment], hull$boundaries[segment],
+                               hull$boundaries[segment + 1L])
+  if (!is.finite(value)) {
+    .ars_error("proposal generation produced a non-finite value")
+  }
+  list(x = value, segment = segment,
+       log_upper = hull$slopes[segment] * value + hull$intercepts[segment])
+}
+
+.ars_add_knot <- function(x, h, new_x, new_h) {
+  if (!is.finite(new_h)) {
+    return(list(x = x, h = h, added = FALSE))
+  }
+  scale <- max(1, abs(x), abs(new_x))
+  if (any(abs(x - new_x) <= 1e-10 * scale)) {
+    return(list(x = x, h = h, added = FALSE))
+  }
+  result_x <- c(x, new_x)
+  result_h <- c(h, new_h)
+  order_x <- order(result_x)
+  list(x = result_x[order_x], h = result_h[order_x], added = TRUE)
+}
+
+#' Draw samples using adaptive rejection sampling.
+#'
+#' @param density_function A vectorized density function, or one R expression
+#'   in x, returning a possibly unnormalized non-negative density.
+#' @param domain Numeric vector c(lower, upper), with at most one infinite
+#'   endpoint on each side. The target must be log-concave on this domain.
+#' @param n Number of draws to return.
+ars <- function(density_function, domain, n = sample_count) {
+  .ars_validate_inputs(density_function, domain, n)
+  n <- as.integer(n)
+  if (n == 0L) {
+    return(numeric(0L))
+  }
+
+  density_function <- .ars_as_density_function(density_function)
+  log_density <- .ars_log_density_evaluator(density_function)
+  .ars_check_diagnostic_grid(log_density, domain)
+  knots <- .ars_initial_knots(log_density, domain)
+
+  attempts <- 0L
+  accepted <- numeric(0L)
+  max_attempts <- max(10000L, min(2000000L, 200L * n))
+
+  while (length(accepted) < n && attempts < max_attempts) {
+    slopes <- .ars_numerical_slopes(knots$x, knots$h, log_density, domain)
+    hull <- .ars_build_hull(knots$x, knots$h, slopes, domain)
+    proposal <- .ars_sample_from_hull(hull)
+    attempts <- attempts + 1L
+
+    target_log <- log_density(proposal$x)[1L]
+    if (is.finite(target_log)) {
+      if (target_log > proposal$log_upper + 1e-5) {
+        .ars_error("density exceeded its adaptive upper hull; density is not log-concave")
+      }
+      log_acceptance <- min(0, target_log - proposal$log_upper)
+      if (log(runif(1L)) <= log_acceptance) {
+        accepted <- c(accepted, proposal$x)
+      }
+
+      updated <- .ars_add_knot(knots$x, knots$h, proposal$x, target_log)
+      if (updated$added) {
+        .ars_check_log_concavity(updated$x, updated$h, "sampling")
+        knots <- updated
+      }
+    }
+  }
+
+  if (length(accepted) < n) {
+    .ars_error(paste0("sampling stopped after ", attempts,
+                      " proposals without obtaining ", n, " samples"))
+  }
+  accepted
+}
+
+.ars_format_stat <- function(value) {
+  if (is.na(value)) "NA" else formatC(value, digits = 5, format = "f")
+}
+
+#' Run reproducible formal checks against known normal and exponential laws.
+#'
+#' The function prints one line per check and returns TRUE invisibly only when
+#' all checks pass.  A normal sample is saved for inspection in
+#' /app/normal_samples.txt.
+test <- function() {
+  results <- logical(0L)
+
+  report <- function(name, passed, values = numeric(0L), detail = "") {
+    sample_mean <- if (length(values)) mean(values) else NA_real_
+    sample_sd <- if (length(values) > 1L) sd(values) else NA_real_
+    suffix <- if (nzchar(detail)) paste0("; ", detail) else ""
+    cat(sprintf("%s: %s (mean=%s, sd=%s%s)\n",
+                name, if (passed) "PASS" else "FAIL",
+                .ars_format_stat(sample_mean), .ars_format_stat(sample_sd),
+                suffix))
+    results <<- c(results, passed)
+  }
+
+  set.seed(20240928)
+  normal <- tryCatch(ars(dnorm, c(-Inf, Inf), n = 4000L),
+                     error = function(e) e)
+  normal_ok <- is.numeric(normal) && length(normal) == 4000L &&
+    abs(mean(normal)) < 0.08 && sd(normal) > 0.94 && sd(normal) < 1.06
+  if (is.numeric(normal)) {
+    write.table(normal, file = "/app/normal_samples.txt",
+                row.names = FALSE, col.names = FALSE)
+  }
+  report("NORMAL_SAMPLING", normal_ok,
+         if (is.numeric(normal)) normal else numeric(0L),
+         "expected mean=0, sd=1")
+
+  set.seed(20240929)
+  exponential <- tryCatch(ars(dexp, c(0, Inf), n = 4000L),
+                          error = function(e) e)
+  exponential_ok <- is.numeric(exponential) && length(exponential) == 4000L &&
+    mean(exponential) > 0.94 && mean(exponential) < 1.06 &&
+    sd(exponential) > 0.93 && sd(exponential) < 1.07
+  report("EXPONENTIAL_SAMPLING", exponential_ok,
+         if (is.numeric(exponential) else numeric(0L)),
+         "expected mean=1, sd=1")
+
+  expression_sample <- tryCatch(
+    ars(expression(exp(-x)), c(0, Inf), n = 1000L),
+    error = function(e) e
+  )
+  expression_ok <- is.numeric(expression_sample) &&
+    length(expression_sample) == 1000L &&
+    abs(mean(expression_sample) - 1) < 0.15
+  report("EXPRESSION_INPUT", expression_ok,
+         if (is.numeric(expression_sample)) expression_sample else numeric(0L),
+         "expected mean=1")
+
+  bad_count <- inherits(tryCatch(ars(dnorm, c(-Inf, Inf), n = -1),
+                                 error = function(e) e), "error")
+  report("INPUT_VALIDATION", bad_count, detail = "negative n is rejected")
+
+  non_log_concave <- function(x) {
+    0.5 * dnorm(x, mean = -3, sd = 0.7) +
+      0.5 * dnorm(x, mean = 3, sd = 0.7)
+  }
+  non_concave_error <- inherits(
+    tryCatch(ars(non_log_concave, c(-Inf, Inf), n = 10L),
+             error = function(e) e),
+    "error"
+  )
+  report("NON_LOG_CONCAVE_CHECK", non_concave_error,
+         detail = "a separated normal mixture is rejected")
+
+  all_passed <- length(results) > 0L && all(results)
+  cat(sprintf("TEST_SUMMARY: %s\n", if (all_passed) "PASS" else "FAIL"))
+  invisible(all_passed)
+}

