.ars_numerical_slopes <- function(x, h, log_density, domain) {
  slopes <- numeric(length(x))
  for (i in seq_along(x)) {
    scale <- max(1, abs(x[i]))
    step <- max(1e-6, 1e-5 * scale)
    if (is.finite(domain[1L])) {
      step <- min(step, (x[i] - domain[1L]) / 2)
    }
    if (is.finite(domain[2L])) {
      step <- min(step, (domain[2L] - x[i]) / 2)
    }
    if (!is.finite(step) || step <= 0) {
      .ars_error("could not choose a finite-difference step for the density")
    }

    left_x <- x[i] - step
    right_x <- x[i] + step
    left_h <- log_density(left_x)[1L]
    right_h <- log_density(right_x)[1L]
    if (is.finite(left_h) && is.finite(right_h)) {
      slopes[i] <- (right_h - left_h) / (2 * step)
    } else if (is.finite(right_h) && is.finite(h[i])) {
      slopes[i] <- (right_h - h[i]) / step
    } else if (is.finite(left_h) && is.finite(h[i])) {
      slopes[i] <- (h[i] - left_h) / step
    } else {
      .ars_error("could not estimate a finite log-density slope")
    }
  }

  if (any(!is.finite(slopes))) {
    .ars_error("density has a non-finite numerical log-density slope")
  }
  tolerance <- .ars_concavity_tolerance(slopes)
  if (length(slopes) > 1L && any(diff(slopes) > tolerance)) {
    .ars_error("density is not log-concave (numerical tangent slopes increase)")
  }
  slopes
}

