.ars_numerical_slopes <- function(x, h, log_density, domain) {
  scale <- pmax(1, abs(x))
  steps <- pmax(1e-6, 1e-5 * scale)
  if (is.finite(domain[1L])) {
    steps <- pmin(steps, (x - domain[1L]) / 2)
  }
  if (is.finite(domain[2L])) {
    steps <- pmin(steps, (domain[2L] - x) / 2)
  }
  if (any(!is.finite(steps)) || any(steps <= 0)) {
    .ars_error("could not choose finite-difference steps for the density")
  }

  left_h <- log_density(x - steps)
  right_h <- log_density(x + steps)
  central <- is.finite(left_h) & is.finite(right_h)
  right_only <- !central & is.finite(right_h) & is.finite(h)
  left_only <- !central & !right_only & is.finite(left_h) & is.finite(h)
  if (any(!central & !right_only & !left_only)) {
    .ars_error("could not estimate a finite log-density slope")
  }

  slopes <- numeric(length(x))
  slopes[central] <- (right_h[central] - left_h[central]) /
    (2 * steps[central])
  slopes[right_only] <- (right_h[right_only] - h[right_only]) /
    steps[right_only]
  slopes[left_only] <- (h[left_only] - left_h[left_only]) /
    steps[left_only]

  if (any(!is.finite(slopes))) {
    .ars_error("density has a non-finite numerical log-density slope")
  }
  tolerance <- .ars_concavity_tolerance(slopes)
  if (length(slopes) > 1L && any(diff(slopes) > tolerance)) {
    .ars_error("density is not log-concave (numerical tangent slopes increase)")
  }
  slopes
}

