source('/app/ars.R')
run <- function(label, expr) {
  out <- tryCatch(expr, error=function(e)e)
  if (inherits(out,'error')) cat(label, 'ERROR:', conditionMessage(out), '\n')
  else cat(label, 'OK n=',length(out),'mean=',mean(out),'sd=',sd(out),'range=',paste(range(out),collapse=','),'\n')
